package com.nigson.commerce.inventory;
import java.util.*;
import java.time.Clock;
import java.nio.charset.StandardCharsets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
/** Staff stock commands are entirely local, with current authority before replay and under lock. */
public final class InventoryService {
 private final InventoryRepository repository;private final InventoryAuthority authority;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final TransactionTemplate reads;private final JdbcTemplate jdbc;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public InventoryService(InventoryRepository repository,InventoryAuthority authority,PlatformStore commands,AuditWriter audit,Clock clock,PlatformTransactionManager manager,JdbcTemplate jdbc,io.micrometer.core.instrument.MeterRegistry metrics){this.repository=repository;this.authority=authority;this.commands=commands;this.audit=audit;this.clock=clock;this.jdbc=jdbc;this.metrics=metrics;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setTimeout(3);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
 public InventoryValues.Page list(ActorAssertion.Actor actor,InventoryValues.Query query){authority.require(actor);return reads.execute(status->{jdbc.execute("SET LOCAL statement_timeout='1500ms'");return repository.list(query);});}
 private void input(ActorAssertion.Actor actor,String key,UUID correlation){authority.require(actor);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();}
 private void lock(ActorAssertion.Actor actor){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2000ms'");authority.stabilize(actor);}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String api,String key,tools.jackson.databind.JsonNode input,java.util.function.Function<JdbcTemplate,PlatformStore.Response> callback){try{return commands.executeLocal(actor.party().toString(),api,key,input,callback);}catch(org.springframework.dao.DataAccessException failed){for(Throwable cause=failed;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failed;}}
 public InventoryValues.Location create(ActorAssertion.Actor actor,InventoryValues.NewLocation input,String key,UUID correlation){input(actor,key,correlation);var response=execute(actor,"API-170",key,EventCodec.JSON.valueToTree(input),db->{lock(actor);var created=repository.create(input,actor.party().toString());audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.STOCK_LOCATION_CREATE,AuditValues.Resource.INVENTORY,created.id(),correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("version",0,"enabled",true),null);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(created),created.id());});return EventCodec.JSON.treeToValue(response.body(),InventoryValues.Location.class);}
 public InventoryValues.Stock adjust(ActorAssertion.Actor actor,InventoryValues.Adjustment input,long expected,String key,UUID correlation){input(actor,key,correlation);if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();String movement="API-046:"+actor.party()+":"+EventCodec.digest(key);var canonical=EventCodec.JSON.valueToTree(Map.of("version",expected,"body",input));var response=execute(actor,"API-046",key,canonical,db->{lock(actor);var changed=repository.adjust(input,expected,movement,actor.party().toString());audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.STOCK_ADJUSTMENT,AuditValues.Resource.INVENTORY,changed.balance(),correlation,AuditValues.Reason.OPERATOR_REQUEST,Map.of("version",changed.before().version()),Map.of("version",changed.after().version()),null);event(changed.balance(),changed.after(),actor.party().toString(),correlation);movement("ADJUST");return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(changed.after()),changed.balance());});return EventCodec.JSON.treeToValue(response.body(),InventoryValues.Stock.class);}
 void movement(String type){if(!Set.of("ADJUST","RESERVE","SETTLE","RELEASE","DISPATCH","RETURN").contains(type))throw ApiValues.invalid();if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.inventory.movements","movement_type",type).increment();}});}
 void event(UUID balance,InventoryValues.Stock stock,String actor,UUID correlation){var envelope=new LinkedHashMap<String,Object>();envelope.put("event_id",EventCodec.uuid7(clock.instant()));envelope.put("event_type","inventory.availability.changed.v1");envelope.put("schema_version",1);envelope.put("producer","commerce");envelope.put("occurred_at",clock.instant());envelope.put("aggregate_id",balance);envelope.put("aggregate_version",stock.version());envelope.put("organization_id",null);envelope.put("correlation_id",correlation);var span=io.opentelemetry.api.trace.Span.current().getSpanContext();envelope.put("traceparent",span.isValid()?"00-"+span.getTraceId()+"-"+span.getSpanId()+"-"+span.getTraceFlags().asHex():null);envelope.put("payload",Map.of("sku_id",stock.skuId(),"location_id",stock.locationId(),"available",stock.available()));commands.append(EventCodec.JSON.writeValueAsString(envelope),actor);}
}
